public class Solution {
    public static int minPositive(int[] arr) {
        // CONTRACT: smallest value > 0; returns -1 when the array
        // contains no positive number. arr may be empty.
        int min = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] > 0) {
                min = arr[i];
            }
        }
        return min;
    }
}

